1	// The evaluator the usage review's rules are read by - the ONE piece of code that
2	// turns a declaration in usage-rules.json into a finding. It knows the grammar and
3	// nothing else: not what a counter means, not where a figure comes from, not what
4	// a subject is. The caller supplies those as three functions, which is what keeps a
5	// rule reviewable as a sentence rather than as code (usage-review DESIGN §3).
6	//
7	// THE GRAMMAR, whole:
8	//
9	//   <when> := <term> ('>=' | '<=' | '=') <term>
10	//   <term> := <atom> | <atom> '/' <atom>
11	//   <atom> := ['previous.'] ['median('] <name> [')']  |  <number>
12	//
13	// Four shapes fall out of it - `a / b >= n`, `a / b <= n`, `a = 0`, `a >= n` - and
14	// nothing else parses. A rule that needs more than this is not a rule; it is code,
15	// and the design has none.
16	//
17	// UNKNOWN PROPAGATES. A figure the record does not carry is `null`, never 0, and a
18	// comparison touching one is *not recorded* rather than false: a week frozen before
19	// a counter existed must not read as a week in which nothing happened.
20	
21	const RE_ATOM = /^(previous\.)?(?:(median)\()?([A-Za-z][A-Za-z0-9]*)\)?$/;
22	
23	// One atom → { name, previous, median }, or { value } for a literal number.
24	function parseAtom(text) {
25	  const raw = text.trim();
26	  if (/^-?\d+(\.\d+)?$/.test(raw)) return { value: Number(raw) };
27	  const m = RE_ATOM.exec(raw);
28	  if (!m) throw new Error(`not a figure: ${raw}`);
29	  return { name: m[3], previous: Boolean(m[1]), median: m[2] === 'median' };
30	}
31	
32	const parseTerm = (text) => text.split('/').map(parseAtom);
33	
34	// `when` (or an `and` that is a comparison) → { left, op, right }, each side a list
35	// of one or two atoms. Throws on anything outside the grammar, which is what makes a
36	// malformed rule a loud failure at evaluation rather than a rule that never fires.
37	export function parseComparison(expr) {
38	  const m = /^(.*?)\s*(>=|<=|=)\s*(.*)$/.exec(String(expr ?? '').trim());
39	  if (!m) throw new Error(`not a comparison: ${expr}`);
40	  return { left: parseTerm(m[1]), op: m[2], right: parseTerm(m[3]) };
41	}
42	
43	// An atom's value through the caller's reader. A literal is itself.
44	const atomValue = (atom, read) => (atom.value !== undefined
45	  ? atom.value
46	  : read(atom.name, { previous: atom.previous, median: atom.median }));
47	
48	// A term's value: one atom, or a quotient. A null anywhere is a null throughout -
49	// and so is a zero denominator, which is a ratio nobody can state rather than an
50	// infinite one.
51	function termValue(atoms, read) {
52	  const values = atoms.map((a) => atomValue(a, read));
53	  if (values.some((v) => v === null || v === undefined || !Number.isFinite(v))) return null;
54	  if (values.length === 1) return values[0];
55	  return values[1] === 0 ? null : values[0] / values[1];
56	}
57	
58	const compare = (left, op, right) => (op === '>=' ? left >= right : op === '<=' ? left <= right : left === right);
59	
60	// Does this comparison hold? `true`, `false`, or `null` where a figure it reads is
61	// not recorded.
62	export function holds(comparison, read) {
63	  const left = termValue(comparison.left, read);
64	  const right = termValue(comparison.right, read);
65	  if (left === null || right === null) return null;
66	  return compare(left, comparison.op, right);
67	}
68	
69	// The figures a rule's floor demands, each against the count the floor names. Returns
70	// the first one that is under - `{ name, need, have }` - or null where all of them
71	// hold. A floor figure that is not recorded is under the floor by construction: a
72	// rule cannot be judged on a window that does not carry what it reads.
73	export function underFloor(floor, read) {
74	  for (const [name, need] of Object.entries(floor ?? {})) {
75	    const atom = parseAtom(name);
76	    const have = atomValue(atom, read);
77	    if (have === null || have === undefined || have < need) return { name, need, have: have ?? null };
78	  }
79	  return null;
80	}
81	
82	// The sentence a rule's fields spell, for the report and for a reader checking that
83	// a declaration says what its author meant.
84	export function ruleSentence(rule) {
85	  const floor = Object.entries(rule.floor ?? {}).map(([k, v]) => `${k} ≥ ${v}`).join(' and ');
86	  return [
87	    `over every ${rule.over}${rule.expect ? ` expecting ${rule.expect}` : ''}`,
88	    rule.window === 'now' ? 'as the tree stands' : `in the ${rule.window} window`,
89	    floor ? `where ${floor}` : 'with no floor',
90	    `flag ${rule.when}${rule.and ? ` and ${rule.and.startsWith('!') ? `not ${rule.and.slice(1)}` : rule.and}` : ''}`,
91	    `- cause ${rule.cause}`,
92	  ].join(', ');
93	}
94	
95	// Evaluate every rule over every subject.
96	//
97	//   subjectsOf(rule)       the subjects this rule judges, [{ id, pack, … }]
98	//   figureOf(subject, name, { previous, median, window })   a number, or null
99	//   predicateOf(subject, name)                              a boolean, or null
100	//
101	// Returns `{ findings, notEvaluated }`. `notEvaluated` is as much of the result as
102	// `findings` is: *no findings* means something only when nothing was skipped for
103	// want of a floor, which is the difference between a clean window and a young one.
104	export function evaluateRules(rules, { subjectsOf, figureOf, predicateOf }) {
105	  const findings = [];
106	  const notEvaluated = [];
107	  for (const rule of rules) {
108	    const when = parseComparison(rule.when);
109	    // `and` is either one more comparison, the name of a live predicate, or a
110	    // predicate name prefixed `!` for "and this is NOT true of the subject" - which
111	    // is how two rules reading one record half split the subjects between them
112	    // instead of both claiming all of them. Parsed once per rule so a malformed one
113	    // fails on the rule rather than per subject.
114	    const andComparison = rule.and && /(>=|<=|=)/.test(rule.and) ? parseComparison(rule.and) : null;
115	    for (const subject of subjectsOf(rule)) {
116	      const read = (name, opts) => figureOf(subject, name, { ...opts, window: rule.window });
117	      const short = underFloor(rule.floor, read);
118	      if (short) {
119	        notEvaluated.push({ rule: rule.id, subject: subject.id, pack: subject.pack ?? null, ...short });
120	        continue;
121	      }
122	      const hit = holds(when, read);
123	      if (hit === null) {
124	        notEvaluated.push({ rule: rule.id, subject: subject.id, pack: subject.pack ?? null, name: rule.when, need: null, have: null });
125	        continue;
126	      }
127	      if (!hit) continue;
128	      if (rule.and) {
129	        const negated = !andComparison && rule.and.startsWith('!');
130	        const raw = andComparison
131	          ? holds(andComparison, read)
132	          : predicateOf(subject, negated ? rule.and.slice(1) : rule.and);
133	        // Unknown survives the negation: a predicate that could not be read is
134	        // still unread when the rule asked for its absence.
135	        const also = negated && raw !== null ? !raw : raw;
136	        // A live half that cannot be read is not a finding and not a silence: the
137	        // record's half held, and the review says the pair could not be judged.
138	        if (also === null) {
139	          notEvaluated.push({ rule: rule.id, subject: subject.id, pack: subject.pack ?? null, name: rule.and, need: null, have: null });
140	          continue;
141	        }
142	        if (!also) continue;
143	      }
144	      findings.push({
145	        rule: rule.id,
146	        subject: subject.id,
147	        pack: subject.pack ?? null,
148	        cause: rule.cause,
149	        causes: rule.causes,
150	        open: rule.open,
151	        finding: rule.finding,
152	        recommendation: rule.recommendation,
153	        figures: figuresOf(rule, read),
154	      });
155	    }
156	  }
157	  return { findings, notEvaluated };
158	}
159	
160	// Every figure the rule's own expressions named, both windows where it asked for
161	// both - the evidence the finding carries, so a reader never goes back to the file
162	// the number came from.
163	function figuresOf(rule, read) {
164	  const out = {};
165	  const atoms = [
166	    ...parseComparison(rule.when).left, ...parseComparison(rule.when).right,
167	    ...(rule.and && /(>=|<=|=)/.test(rule.and)
168	      ? [...parseComparison(rule.and).left, ...parseComparison(rule.and).right] : []),
169	    ...Object.keys(rule.floor ?? {}).map(parseAtom),
170	  ];
171	  for (const atom of atoms) {
172	    if (atom.value !== undefined) continue;
173	    const label = `${atom.previous ? 'previous.' : ''}${atom.median ? `median(${atom.name})` : atom.name}`;
174	    out[label] = atomValue(atom, read);
175	  }
176	  return out;
177	}
178

