1	#!/usr/bin/env node
2	// World-scope conformance runner (see DESIGN.md): the rules that audit repo
3	// state as it exists now, plus the pack-agnostic settings/load integrity
4	// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
5	// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
6	// this file shares no code with — only the scope-blind mechanism helpers
7	// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
8	// interview hygiene is a skill-owned check that rides its own pack's activation,
9	// and a malformed `questions` field is a load fault the pack registry reports.
10	// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
11	//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
12	//   --changed   transitional: scope to files changed vs the merge-base with main
13	//               (adopting a repo with a backlog only — not the enforcement default)
14	//   --base REF  override the base ref
15	//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
16	//   --init      write .claudinite-settings.json — basics plus the fingerprinted packs
17	import { buildContext } from './helpers/repo-context.mjs';
18	import { discoverPacks, packEntryId } from '../pack_loader/pack-registry.mjs';
19	import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
20	import { reportFindings } from './report-findings.mjs';
21	
22	const configError = (what, fix) => ({
23	  rule: 'config', severity: 'blocking', file: '.claudinite-settings.json', line: null,
24	  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
25	});
26	
27	const args = process.argv.slice(2);
28	const has = (flag) => args.includes(flag);
29	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
30	// The repo to sweep. `--root` first, then CLAUDE_PROJECT_DIR, and only then the cwd.
31	// The env var is not a convenience: the callers that run this from inside a converge
32	// (the update runner) have a cwd that no longer exists — the vendor step deletes
33	// `.claudinite/shared/`, which is where code-work's cwd lives — and `process.cwd()` then
34	// throws `ENOENT … uv_cwd` before a single check runs, which reads from the outside as
35	// "this mount has no checks" (#689). engine/selftest.mjs has always resolved its root
36	// this way; this closes the disagreement for every caller, not just that one.
37	const root = value('--root') || process.env.CLAUDE_PROJECT_DIR || process.cwd();
38	
39	// A pack that fails to load — a pack.mjs whose import throws, a rule module that
40	// won't load, an unparseable declared-checks.json — is absent from `packs`, with
41	// the reason on `errors`. So a caller reading one without the other cannot tell a
42	// pack that was never there from one that did not load: it emits a short answer
43	// and reports success. The full run below turns those errors into findings; these
44	// two entry points would otherwise be the ones that swallow them (#2008).
45	// A null return means the caller prints NOTHING and the run ends on the exit code
46	// set here. It cannot call process.exit itself: see the note on exiting below.
47	async function wholeRegistryOr(exit) {
48	  const { packs, errors } = await discoverPacks({ localRoot: root });
49	  if (errors.length) {
50	    console.error(`${errors.length} pack(s) failed to load, so ${exit} cannot answer for this repo:`);
51	    for (const e of errors) console.error(`  ${e.what}\n    Fix: ${e.fix}`);
52	    process.exitCode = 1;
53	    return null;
54	  }
55	  return packs;
56	}
57	
58	// EXITING: set process.exitCode and let the process end on its own — never
59	// process.exit(). When stdout is a PIPE (which is every caller that captures the
60	// output: a test's spawnSync, a shell pipeline, an Actions step) a write is
61	// ASYNCHRONOUS, and process.exit() drops whatever is still queued. That is not
62	// theoretical: the catalog below is ~150 rows, and under load a quarter of runs
63	// handed the caller a catalog cut off at a row boundary — status 0, empty stderr,
64	// a silently short answer, which is the worst shape a machine-readable channel can
65	// fail in. The branches below are an if/else chain for the same reason: an exit
66	// code does not stop the script the way process.exit did.
67	if (has('--list')) {
68	  // stdout stays the machine-readable channel; the diagnostic above goes to stderr.
69	  const packs = await wholeRegistryOr('--list');
70	  if (packs) {
71	    // One write rather than one per rule — less for the exit to have to flush, and
72	    // a catalog is a single document, not a stream.
73	    // A declared check carries neither a description nor a doc pointer — it
74	    // states its own case — so the catalog prints its failure message in that
75	    // column and leaves the pointer empty.
76	    console.log(packRules(packs)
77	      .map((r) => `${r.id}\t${r.severity}\t${r.description ?? r.why ?? ''}\t${r.doc ?? ''}`)
78	      .join('\n'));
79	  }
80	} else if (has('--init')) {
81	  const { seedDeclaration } = await import('./helpers/seed-declaration.mjs');
82	  // A declaration seeded from a partial registry omits the packs that did not
83	  // load, and a member copies that file once and never again — so refuse rather
84	  // than write one.
85	  const packs = await wholeRegistryOr('--init');
86	  if (packs) {
87	    const { path, existed, declared } = seedDeclaration(root, packs);
88	    // The adoption interview (surfacing each declared pack's pending questions) is
89	    // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
90	    // by the SessionStart interview-check step — not printed here, so this runner
91	    // imports no pack.
92	    console.log(existed
93	      ? `${path} already exists — leaving it as-is.`
94	      : `Wrote ${path} (packs: ${declared.map(packEntryId).join(', ')}).`);
95	  }
96	} else {
97	  await sweep();
98	}
99	
100	// The sweep itself. A function only so the branches above can end the run without
101	// process.exit — see the note on exiting.
102	async function sweep() {
103	  const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
104	  const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });
105	
106	  // Settings/load integrity — pack-agnostic, so the world runner owns them.
107	  // Settings validity is checked at load: malformed JSON, an unknown
108	  // property, and a wrong pack name are all equally settings errors. loadConfig
109	  // reports the first two; the runner adds unknown pack names (only it holds the
110	  // registry) and broken/duplicate local pack.mjs faults.
111	  const findings = [];
