1	// The usage review's I/O shell: read the record, read the tree, evaluate the rules,
2	// write the file, move the dashboard and the issues. Every decision is in a
3	// declaration or in a tested pure function - this file only moves data between them.
4	//
5	// It changes NOTHING it reviews. Not a pack element, not a provenance log, not a
6	// severity. The file it writes and the issues it files are an analysis with a
7	// recommendation attached; the one stage that edits anything is `usage-triage`, and
8	// the owner merges that or declines it.
9	import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
10	import { join, dirname } from 'node:path';
11	import { fileURLToPath } from 'node:url';
12	import { deliverGenerated, baseTip, remoteUrl, readAt } from '../../../claudinite-tasks/public/delivery.mjs';
13	import { evaluateRules } from './evaluate.mjs';
14	import { figureReader } from './figures.mjs';
15	import { readWindows } from './read-record.mjs';
16	import { readSkills, readRules, acceptanceReader, acceptanceReasons, packDeclaredAt, adoptionWindow } from './read-live.mjs';
17	import { captureFiles, sampleDigests } from './digests.mjs';
18	import { reviewFile, dashboardValues, prBody, findingKey, REVIEW_PATH, DASHBOARD_PATH } from './report.mjs';
19	
20	const here = dirname(fileURLToPath(import.meta.url));
21	const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
22	const repo = process.env.CLAUDINITE_REPO;
23	const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
24	const token = process.env.GITHUB_TOKEN;
25	const log = (m) => console.log(`usage-review: ${m}`);
26	
27	const engine = (mod) => join(root, '.claudinite', 'shared', 'engine', mod);
28	const engineOrLocal = async (mod) => {
29	  try { return await import(engine(mod)); } catch { return import(join(root, 'engine', mod)); }
30	};
31	
32	// The findings whose rules want a sample of what the sessions were doing: the one
33	// that asks whether a skill should have loaded in a window where it did not.
34	const WANTS_DIGESTS = new Set(['skill-adoption-not-reached']);
35	
36	async function main() {
37	  const config = JSON.parse(readFileSync(join(root, '.claudinite-settings.json'), 'utf8'));
38	  const { loadPacks, isActive } = await engineOrLocal('pack_loader/pack-registry.mjs');
39	  const { packRules } = await engineOrLocal('checks/run-active-pack-rules.mjs');
40	  const packs = (await loadPacks({ localRoot: root })).filter((p) => isActive(p, config));
41	
42	  const today = new Date().toISOString().slice(0, 10);
43	  const record = readWindows(root, today);
44	  if (!record) { log('no usage fold to review yet - nothing to do'); return; }
45	
46	  const skills = await readSkills(root, packs);
47	  const { check, guard } = readRules(packs, packRules(packs));
48	  const acceptancesOf = acceptanceReader(config);
49	  const live = { acceptancesOf };
50	
51	  // A skill expecting `adoption` is judged only once its pack's adoption window has
52	  // closed: inside it, a skill that has not loaded may simply not have been reached.
53	  const declaredAt = new Map(packs.map((p) => [p.id, packDeclaredAt(root, p.id)]));
54	  const adoptionClosed = (skill) => adoptionWindow(declaredAt.get(skill.pack), new Date().toISOString())?.closed === true;
55	
56	  const subjectsOf = (rule) => {
57	    if (rule.over === 'checks') return [{ id: 'checks', pack: null }];
58	    if (rule.over === 'check') return check;
59	    if (rule.over === 'guard') return guard;
60	    let set = skills;
61	    if (rule.expect) set = set.filter((s) => s.expect === rule.expect);
62	    if (rule.window === 'adoption') set = set.filter(adoptionClosed);
63	    return set;
64	  };
65	
66	  const readFigure = figureReader({ window: record.window, previous: record.previous, live });
67	  const rules = JSON.parse(readFileSync(join(here, '..', '..', 'usage-rules.json'), 'utf8')).rules;
68	  const { findings, notEvaluated } = evaluateRules(rules, {
69	    subjectsOf,
70	    figureOf: readFigure,
71	    predicateOf: (subject, name) => (name === 'proseTwin' ? subject.proseTwin ?? null : null),
72	  });
73	
74	  // `since` - the first review this finding appeared in - comes from the PRIOR file
75	  // at the base tip, never from local HEAD: the checkout may be sitting on this
76	  // task's own open pull request, and the base is the only authority on what has
77	  // already been reviewed.
78	  const remote = remoteUrl(repo, token);
79	  const priorText = token && repo ? readAt(root, baseTip(root, remote, base), REVIEW_PATH) : null;
80	  const prior = priorText ? JSON.parse(priorText) : null;
81	  const priorSince = new Map((prior?.findings ?? []).map((f) => [findingKey(f), f.since]));
82	  for (const finding of findings) finding.since = priorSince.get(findingKey(finding)) ?? today;
83	
84	  // The evidence, attached: a reader never goes back to a transcript to judge one.
85	  const captures = captureFiles(root);
86	  if (!captures.length) log('no capture branch - digests recorded as not sampled');
87	  for (const finding of findings) {
88	    if (!WANTS_DIGESTS.has(finding.rule)) continue;
89	    finding.digests = captures.length
90	      ? sampleDigests(root, captures, { from: record.window.from, to: record.window.to })
91	      : null;
92	  }
93	  for (const finding of findings) {
94	    if (finding.rule !== 'check-accepted-away') continue;
95	    finding.acceptances = acceptanceReasons(config, finding.subject);
96	  }
97	
98	  const unstated = skills.filter((s) => s.expect === null).map((s) => ({ skill: s.id, pack: s.pack }));
99	  const file = reviewFile({ record, findings, notEvaluated, unstated, skills, check, guard, today });
100	
101	  writeFileSync(join(root, REVIEW_PATH), `${JSON.stringify(file, null, 2)}\n`);
102	  mkdirSync(join(root, dirname(DASHBOARD_PATH)), { recursive: true });
103	  const dashboard = `${JSON.stringify(dashboardValues(file, prior), null, 2)}\n`;
104	  writeFileSync(join(root, DASHBOARD_PATH), dashboard);
105	  log(`${findings.length} findings, ${notEvaluated.length} not evaluated, ${unstated.length} skills unstated`);
106	
107	  if (!token || !repo) { log('no token - the file is written, nothing delivered'); return; }
108	
109	  await deliverGenerated({
110	    root, repo, base, token,
111	    branch: process.env.CLAUDINITE_TARGET_BRANCH || null,
112	    pr: process.env.CLAUDINITE_TARGET_PR ? Number(process.env.CLAUDINITE_TARGET_PR) : null,
113	    branchPrefix: 'claudinite/usage-review',
114	    files: { [REVIEW_PATH]: `${JSON.stringify(file, null, 2)}\n`, [DASHBOARD_PATH]: dashboard },
115	    title: `Usage review: ${findings.length} findings in the 28 days to ${record.window.to}`,
116	    body: prBody(file),
117	    message: `Usage review for the 28 days to ${record.window.to}`,
118	    task: 'claudinite-growth/usage-review',
119	    log,
120	  });
121	
122	  await syncIssues(file);
123	}
124	
125	// One issue per (rule, subject) whose finding has lasted two weeks with a cause
126	// worth reading, updated in place while it persists and closed the day it clears.
127	// A finding with an `unknown` cause never files: it stays in the file and on the
128	// dashboard, which is where evidence belongs until it is more than evidence.
129	async function syncIssues(file) {
130	  const { filingsFor, closuresFor, issueTitle, issueBody, closingComment } = await import('./issues.mjs');
131	  const api = async (path, init) => {
132	    const res = await fetch(`https://api.github.com${path}`, {
133	      ...init,
134	      headers: { authorization: `Bearer ${token}`, accept: 'application/vnd.github+json', 'content-type': 'application/json' },
135	      body: init?.body ? JSON.stringify(init.body) : undefined,
136	    });
137	    return { status: res.status, json: await res.json().catch(() => null) };
138	  };
139	  const { json: open } = await api(`/repos/${repo}/issues?state=open&labels=usage-finding&per_page=100`);
140	  const byTitle = new Map((Array.isArray(open) ? open : []).map((i) => [i.title, i]));
141	
142	  for (const finding of filingsFor(file)) {
143	    const title = issueTitle(finding);
144	    const existing = byTitle.get(title);
145	    const body = issueBody(finding, file);
146	    if (existing) {
147	      await api(`/repos/${repo}/issues/${existing.number}`, { method: 'PATCH', body: { body } });
148	      log(`updated #${existing.number} - ${title}`);
149	    } else {
150	      const { json } = await api(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: ['usage-finding'] } });
151	      log(`filed #${json?.number ?? '?'} - ${title}`);
152	    }
153	  }
154	  for (const stale of closuresFor(file, [...byTitle.keys()])) {
155	    const issue = byTitle.get(stale.title);
156	    if (!issue) continue;
157	    await api(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body: closingComment(stale, file) } });
158	    await api(`/repos/${repo}/issues/${issue.number}`, { method: 'PATCH', body: { state: 'closed', state_reason: 'completed' } });
159	    log(`closed #${issue.number} - the finding cleared`);
160	  }
161	}
162	
163	if (process.argv[1] && process.argv[1].endsWith('worker.mjs')) {
164	  main().catch((e) => { console.error(`claudinite-needs-human: failure - ${e.message}`); process.exit(1); });
165	}
166

