const was=JSON.parse(require('child_process').execFileSync('git',['show','HEAD:.claudinite/local/usage-review.GENERATED.json'],{encoding:'utf8',maxBuffer:1e8}));
const count=(f)=>{const o={};for(const x of f.findings)o[x.rule]=(o[x.rule]||0)+1;return o;};
console.log('BEFORE', JSON.stringify(count(was),null,1));
console.log('AFTER ', JSON.stringify(count(now),null,1));
console.log('cannot-reach subjects:', now.findings.filter(f=>f.rule==='check-cannot-reach').map(f=>f.subject).join(', '));
const nf=now.findings.filter(f=>f.rule==='check-never-fires').slice(0,3);
console.log('sample never-fires figures:', JSON.stringify(nf.map(f=>({s:f.subject,fig:f.figures}))));
const ne=now.notEvaluated.filter(n=>n.name==='opportunities').length;
console.log('notEvaluated on opportunities:', ne, 'of', now.notEvaluated.length);
"

